import { View, Text, Pressable, Animated, StyleSheet } from "react-native";
import { useRef } from "react";
import { registerRootComponent } from "expo";

function App() {
  const rate = useRef(new Animated.Value(0)).current;
  // энд бичнэ үү: width-г rate-аас interpolate хий (0→1 → 0→240)
  const width = 0;
  const fill = () => Animated.timing(rate, { toValue: 1, duration: 500 }).start();
  return (
    <View style={styles.s}>
      <View style={styles.track}>
        <Animated.View nativeID="stars" style={[styles.fill, { width }]} />
      </View>
      <Pressable nativeID="rate" style={styles.b} onPress={fill}><Text style={styles.t}>Үнэлэх</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, padding: 24, alignItems: "center", justifyContent: "center" },
  track: { width: 240, height: 20, backgroundColor: "#f1f5f9", borderRadius: 8, overflow: "hidden" },
  fill: { height: 20, backgroundColor: "#f59e0b" },
  b: { backgroundColor: "#2563eb", padding: 12, borderRadius: 10 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, Animated, StyleSheet } from "react-native";
import { useRef } from "react";
import { registerRootComponent } from "expo";

function App() {
  const rate = useRef(new Animated.Value(0)).current;
  const width = rate.interpolate({ inputRange: [0, 1], outputRange: [0, 240] });
  const fill = () => Animated.timing(rate, { toValue: 1, duration: 500 }).start();
  return (
    <View style={styles.s}>
      <View style={styles.track}>
        <Animated.View nativeID="stars" style={[styles.fill, { width }]} />
      </View>
      <Pressable nativeID="rate" style={styles.b} onPress={fill}><Text style={styles.t}>Үнэлэх</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, padding: 24, alignItems: "center", justifyContent: "center" },
  track: { width: 240, height: 20, backgroundColor: "#f1f5f9", borderRadius: 8, overflow: "hidden" },
  fill: { height: 20, backgroundColor: "#f59e0b" },
  b: { backgroundColor: "#2563eb", padding: 12, borderRadius: 10 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
